BEGIN TRANSACTION;
CREATE TABLE "danger_levels" (
"district" TEXT,
  "danger_level" TEXT,
  "danger_index" INTEGER,
  "main_risk" TEXT,
  "reference_period" TEXT,
  "data_status" TEXT
);
CREATE TABLE "flood_history" (
"uei" TEXT,
  "start_date" TEXT,
  "end_date" TEXT,
  "duration_days" REAL,
  "main_cause" TEXT,
  "location" REAL,
  "districts" TEXT,
  "state" TEXT,
  "latitude" REAL,
  "longitude" REAL,
  "severity" REAL,
  "area_affected" REAL,
  "human_fatality" REAL,
  "human_injured" REAL,
  "human_displaced" REAL,
  "animal_fatality" REAL,
  "extent_of_damage" TEXT,
  "event_source" TEXT,
  "event_souce_id" REAL,
  "district_lgd_codes" TEXT,
  "state_codes" INTEGER
);
CREATE TABLE hazard_assessments (
	assessment_id VARCHAR NOT NULL, 
	household_id VARCHAR, 
	state VARCHAR NOT NULL, 
	district VARCHAR NOT NULL, 
	village VARCHAR, 
	latitude FLOAT NOT NULL, 
	longitude FLOAT NOT NULL, 
	elevation_meters FLOAT, 
	slope_degrees FLOAT, 
	landslide_exposure FLOAT, 
	flood_exposure FLOAT, 
	river_exposure FLOAT, 
	rainfall_exposure FLOAT, 
	distance_to_nearest_river_km FLOAT, 
	distance_to_nearest_hospital_km FLOAT, 
	nearest_hospital_name VARCHAR, 
	composite_hazard_exposure FLOAT NOT NULL, 
	hazard_tier VARCHAR, 
	vulnerability_score FLOAT, 
	vulnerability_level VARCHAR, 
	risk_score FLOAT, 
	risk_level VARCHAR, 
	priority_level VARCHAR, 
	recommended_shelter_id VARCHAR, 
	recommended_shelter_name VARCHAR, 
	shelter_distance_km FLOAT, 
	assessed_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (assessment_id), 
	FOREIGN KEY(household_id) REFERENCES households (household_id) ON DELETE SET NULL
);
