CREATE TABLE households (
	household_id VARCHAR NOT NULL, 
	state VARCHAR NOT NULL, 
	district VARCHAR NOT NULL, 
	village VARCHAR NOT NULL, 
	latitude FLOAT NOT NULL, 
	longitude FLOAT NOT NULL, 
	population INTEGER NOT NULL, 
	children INTEGER NOT NULL, 
	elderly INTEGER NOT NULL, 
	disabled INTEGER NOT NULL, 
	low_income BOOLEAN NOT NULL, 
	hazard_exposure FLOAT, 
	previous_disaster_exposure FLOAT NOT NULL, 
	vulnerability_score FLOAT, 
	vulnerability_level VARCHAR, 
	priority_level VARCHAR, 
	risk_score FLOAT, 
	risk_level VARCHAR, 
	in_historical_flood_zone BOOLEAN, 
	distance_to_nearest_river_km FLOAT, 
	distance_to_nearest_hospital_km FLOAT, 
	nearest_hospital VARCHAR, 
	flood_exposure FLOAT, 
	river_exposure FLOAT, 
	landslide_exposure FLOAT, 
	rainfall_exposure FLOAT, 
	hazard_tier VARCHAR, 
	elevation_meters FLOAT, 
	slope_degrees FLOAT, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (household_id)
);
CREATE TABLE "rainfall_history" (
"rainfall_id" INTEGER,
  "station" TEXT,
  "state" TEXT,
  "district_lgd_code" INTEGER,
  "district" TEXT,
  "latitude" REAL,
  "longitude" REAL,
  "date" TEXT,
  "daily_rainfall_mm" REAL,
  "max_hourly_rainfall_mm" REAL,
  "rainfall_readings" INTEGER
);
CREATE TABLE relocation_centers (
	center_id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	state VARCHAR NOT NULL, 
	district VARCHAR NOT NULL, 
	village VARCHAR NOT NULL, 
	latitude FLOAT NOT NULL, 
	longitude FLOAT NOT NULL, 
	total_capacity INTEGER NOT NULL, 
	current_occupancy INTEGER NOT NULL, 
	medical_support BOOLEAN NOT NULL, 
	food_available BOOLEAN NOT NULL, 
	water_available BOOLEAN NOT NULL, 
	sanitation_available BOOLEAN NOT NULL, 
	accessible_for_disabled BOOLEAN NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, 
	PRIMARY KEY (center_id)
);
CREATE TABLE "river_levels" (
"river_id" INTEGER,
  "station" TEXT,
  "state" TEXT,
  "district_lgd_code" INTEGER,
  "district" TEXT,
  "latitude" REAL,
  "longitude" REAL,
  "date" TEXT,
  "mean_discharge_m3_sec" REAL,
  "max_discharge_m3_sec" REAL,
  "min_discharge_m3_sec" REAL,
  "readings" INTEGER
);
CREATE TABLE "uttarakhand_landslides" (
"sl_no" INTEGER,
  "slide_no" TEXT,
  "state" TEXT,
  "district" TEXT,
  "slide_name" TEXT,
  "nh_sh_location" TEXT,
  "latitude" REAL,
  "longitude" REAL,
  "material_involved" TEXT,
  "movement_type" TEXT,
  "history" TEXT
);
CREATE INDEX ix_households_district ON households (district);
CREATE INDEX ix_households_household_id ON households (household_id);
CREATE INDEX ix_households_state ON households (state);
CREATE INDEX ix_households_village ON households (village);
CREATE INDEX ix_relocation_centers_center_id ON relocation_centers (center_id);
CREATE INDEX ix_relocation_centers_district ON relocation_centers (district);
CREATE INDEX ix_relocation_centers_village ON relocation_centers (village);
CREATE INDEX ix_relocation_centers_state ON relocation_centers (state);
CREATE INDEX ix_hazard_assessments_district ON hazard_assessments (district);
CREATE INDEX ix_hazard_assessments_state ON hazard_assessments (state);
CREATE INDEX ix_hazard_assessments_household_id ON hazard_assessments (household_id);
CREATE INDEX ix_hazard_assessments_assessment_id ON hazard_assessments (assessment_id);
CREATE VIEW danger_level AS SELECT * FROM danger_levels;
CREATE VIEW uttarakhand_danger_levels AS SELECT * FROM danger_levels;
CREATE VIEW uttarakhand_danger_level_qgis AS SELECT * FROM danger_levels;
COMMIT;
